import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  // Auth & UI States
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [authData, setAuthData] = useState({ username: '', password: '' });
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS"); // Fixed: HDFC Bank default for Accuracy Proof
  const [loading, setLoading] = useState(false);

  // 🟢 Final Indian Stock List (As per Google Finance)
  const stockList = [
    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },
    { name: "JSW Steel", symbol: "JSWSTEEL.NS" },
    { name: "HDFC Life", symbol: "HDFCLIFE.NS" },
    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },
    { name: "Paytm (One97)", symbol: "PAYTM.NS" },
    { name: "Zomato", symbol: "ZOMATO.NS" },
    { name: "Sun Pharma", symbol: "SUNPHARMA.NS" },
    { name: "ITC", symbol: "ITC.NS" }
  ];

  const handleAuth = async () => {
    // Endpoints-a prefix kooda check pannikonga
    const endpoint = isSignup ? "/auth/signup" : "/auth/login";
    try {
      const res = await axios.post(`http://localhost:8000${endpoint}`, authData);
      if (isSignup) {
        alert("Signup Success! Now please Login.");
        setIsSignup(false);
      } else {
        setIsLoggedIn(true);
      }
    } catch (err) {
      console.error(err);
      alert("Error: " + (err.response?.data?.detail || "Connection Failed"));
    }
  };
  // Analyze Logic
  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend Error", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    if (isLoggedIn) {
      fetchData(selectedStock);
    }
  }, [selectedStock, isLoggedIn]);

  // --- LOGIN SCREEN ---
 if (!isLoggedIn) {
    return (
      <div style={{ 
        backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url('https://i.ibb.co/XfXkY8C/rm373batch4-07.jpg')`, // Neenga upload panna image-a refer pannudhu
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', fontFamily: "'Poppins', sans-serif" 
      }}>
        <div style={{ 
          background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(15px)', padding: '50px', 
          borderRadius: '30px', border: '1px solid rgba(255, 255, 255, 0.2)', width: '900px',
          display: 'flex', gap: '40px', boxShadow: '0 25px 50px rgba(0,0,0,0.5)', color: 'white'
        }}>
          {/* Left Side: Branding */}
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
             <h1 style={{ fontSize: '48px', fontWeight: '900', margin: '0 0 10px 0', color: '#00f2fe' }}>QuantShield</h1>
             <h3 style={{ fontSize: '20px', fontWeight: '400', opacity: 0.9, color: '#4facfe' }}>Financial Portfolio Optimization and Risk Forecasting</h3>
             <p style={{ fontSize: '14px', marginTop: '20px', lineHeight: '1.6', opacity: 0.8 }}>
                Next-generation AI engine providing sub-second market accuracy and advanced predictive modeling for the modern investor.
             </p>
          </div>

          {/* Right Side: Auth Form */}
          <div style={{ flex: 0.8, background: 'rgba(0, 0, 0, 0.4)', padding: '40px', borderRadius: '25px', border: '1px solid rgba(255,255,255,0.1)' }}>
            <h2 style={{ marginBottom: '25px', letterSpacing: '2px', fontWeight: '700' }}>{isSignup ? "REGISTER" : "ACCESS PORTAL"}</h2>
            <input type="text" placeholder="USERNAME" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '15px', margin: '12px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px', outline: 'none' }} />
            <input type="password" placeholder="PASSWORD" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '15px', margin: '12px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px', outline: 'none' }} />
            <button onClick={handleAuth} style={{ width: '100%', padding: '15px', background: 'linear-gradient(90deg, #00f2fe, #4facfe)', color: '#002f35', border: 'none', borderRadius: '10px', cursor: 'pointer', fontWeight: '900', fontSize: '16px', marginTop: '20px', transition: '0.3s' }}>
              {isSignup ? "CREATE ACCOUNT" : "SIGN IN"}
            </button>
            <p onClick={() => setIsSignup(!isSignup)} style={{ textAlign: 'center', marginTop: '20px', cursor: 'pointer', fontSize: '13px', color: '#00f2fe' }}>
              {isSignup ? "Back to Login" : "Don't have an account? Sign Up"}
            </p>
          </div>
        </div>
      </div>
    );
  }

  // --- DASHBOARD SCREEN ---
// --- Replace your return statement with this updated UI ---
return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
      
      {/* 🟢 SIDEBAR (Inspired by NextAdmin) */}
      <div style={{ width: '260px', background: 'white', padding: '30px 20px', borderRight: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column' }}>
        <h2 style={{ color: '#4facfe', fontWeight: '800', marginBottom: '40px', fontSize: '22px' }}>🛡️ QuantShield</h2>
        <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '20px', letterSpacing: '1px' }}>MAIN MENU</div>
        <div style={{ background: '#f4f7fe', color: '#4facfe', padding: '12px 15px', borderRadius: '10px', fontWeight: 'bold', marginBottom: '10px', cursor: 'pointer' }}>📁 Dashboard</div>
        <div style={{ padding: '12px 15px', color: '#64748b', cursor: 'pointer' }}>📈 Analytics</div>
        <div style={{ padding: '12px 15px', color: '#64748b', cursor: 'pointer' }}>💹 Stocks</div>
        <div style={{ padding: '12px 15px', color: '#64748b', cursor: 'pointer' }}>⚙️ Settings</div>
        <div style={{ marginTop: 'auto', padding: '15px', borderTop: '1px solid #e2e8f0', color: '#f85149', cursor: 'pointer', fontWeight: 'bold' }} onClick={() => setIsLoggedIn(false)}>Logout</div>
      </div>

      {/* 🔵 MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '40px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
          <div>
            <h1 style={{ margin: 0, fontSize: '28px', fontWeight: '800', color: '#1e293b' }}>Dashboard</h1>
            <p style={{ color: '#64748b', margin: '5px 0 0 0' }}>Financial Portfolio Optimization and Risk Forecasting System</p>
          </div>
          <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
             <input type="text" placeholder="Search..." style={{ padding: '10px 20px', borderRadius: '30px', border: '1px solid #e2e8f0', outline: 'none' }} />
             <div style={{ width: '40px', height: '40px', borderRadius: '50%', background: '#4facfe', display:'flex', justifyContent:'center', alignItems:'center', color:'white', fontWeight:'bold' }}>S</div>
          </div>
        </div>

        {/* TOP ASSET SELECTOR CARD */}
        <div style={{ background: 'white', padding: '20px', borderRadius: '20px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', marginBottom: '30px', display: 'flex', alignItems: 'center', gap: '20px' }}>
            <span style={{ fontWeight: 'bold', color: '#64748b' }}>Select Asset:</span>
            <select value={selectedStock} onChange={(e) => setSelectedStock(e.target.value)} style={{ padding: '10px 20px', borderRadius: '10px', border: '1px solid #e2e8f0', background: '#f8fafc', outline: 'none', cursor: 'pointer' }}>
                {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name}</option>)}
            </select>
            {loading && <span style={{ color: '#4facfe', fontSize: '14px' }}>Syncing Live NSE Data...</span>}
        </div>

        {data && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
            {/* MINI CARDS (Inspired by NextAdmin) */}
            <MiniCard title="Current Price" value={`₹${data.current_price}`} color="#4facfe" />
            <MiniCard title="Volatility" value={data.volatility} color="#f85149" />
            <MiniCard title="BSI Momentum" value={data.bsi_score} color="#d2a8ff" />
            <MiniCard title="Protection (CPS)" value={data.cps_score} color="#3fb950" />
          </div>
        )}

        {data && (
          <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '30px' }}>
            
            {/* LEFT BIG CARD: AI FORECAST */}
            <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
              <h3 style={{ marginBottom: '20px', color: '#1e293b' }}>AI Predictive Analysis</h3>
              <div style={{ height: '200px', background: 'linear-gradient(180deg, #f8fafc, white)', borderRadius: '20px', border: '1px solid #f1f5f9', display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column' }}>
                 <div style={{ fontSize: '14px', color: '#64748b' }}>Target Price (Day 2)</div>
                 <div style={{ fontSize: '48px', fontWeight: '800', color: '#1e293b' }}>₹{data.prediction?.day2}</div>
                 <div style={{ color: data.prediction?.trend === "UP" ? '#3fb950' : '#f85149', fontWeight: 'bold' }}>{data.prediction?.pct} {data.prediction?.trend}</div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginTop: '20px' }}>
                <div style={{ padding: '20px', background: '#f0fdf4', borderRadius: '15px', border: '1px solid #dcfce7' }}>
                   <span style={{ fontSize: '12px', color: '#166534' }}>Expected Return</span>
                   <h3 style={{ margin: '5px 0', color: '#16a34a' }}>₹{data.forecast?.expected}</h3>
                </div>
                <div style={{ padding: '20px', background: '#fef2f2', borderRadius: '15px', border: '1px solid #fee2e2' }}>
                   <span style={{ fontSize: '12px', color: '#991b1b' }}>Risk Scenario</span>
                   <h3 style={{ margin: '5px 0', color: '#dc2626' }}>₹{data.forecast?.worst_case}</h3>
                </div>
              </div>
            </div>

            {/* RIGHT CARD: AI VERDICT */}
            <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center' }}>
                <h3 style={{ marginBottom: '30px', color: '#1e293b' }}>AI Recommendation</h3>
                <div style={{ 
                    width: '100%', padding: '40px 20px', borderRadius: '20px', 
                    background: data.decision === "BUY" ? '#f0fdf4' : data.decision === "AVOID" ? '#fef2f2' : '#fffbeb',
                    border: `2px solid ${data.decision === "BUY" ? '#22c55e' : data.decision === "AVOID" ? '#ef4444' : '#f59e0b'}`,
                    color: data.decision === "BUY" ? '#166534' : data.decision === "AVOID" ? '#991b1b' : '#92400e'
                }}>
                    <div style={{ fontSize: '14px', fontWeight: 'bold', marginBottom: '10px' }}>OFFICIAL VERDICT</div>
                    <div style={{ fontSize: '32px', fontWeight: '900' }}>{data.decision}</div>
                </div>
                <p style={{ fontSize: '12px', color: '#64748b', marginTop: '20px' }}>Based on sub-second market volatility and momentum indices.</p>
            </div>

          </div>
        )}
      </div>
    </div>
  );
}

// 🟢 MINI CARD COMPONENT
function MiniCard({ title, value, color }) {
  return (
    <div style={{ background: 'white', padding: '25px', borderRadius: '20px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', border: '1px solid #f1f5f9' }}>
      <div style={{ color: '#64748b', fontSize: '14px', marginBottom: '10px', fontWeight: 'bold' }}>{title}</div>
      <div style={{ fontSize: '24px', fontWeight: '800', color: '#1e293b' }}>{value}</div>
      <div style={{ marginTop: '10px', width: '40px', height: '4px', background: color, borderRadius: '2px' }}></div>
    </div>
  );
}

export default App;
